import { useEffect, useMemo, useRef, useState, type KeyboardEvent } from 'react'
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Talks to the precedence-table module in terminals and relations only (no keys, pruning or $ handling here);
//          the G_expr2 example is a project operation that also fills the terminals and the table.
import {
  analyzePrec,
  clearRelations,
  cycleRelation,
  parseTerminals,
  precTable,
  relation,
  setRelation,
  setTerminals,
  type Prec,
  type Rel,
} from '#/lib/precedence'
import { hasPrecTable, loadPrecExample } from '#/lib/precOps'
import type { ProjectData } from '#/lib/project'
import ClickSpark from './reactbits/ClickSpark'
import { Button, DangerButton, Help, ListTable, Panel, PrimaryButton, Problems, ResultLine, TextArea, TextInput, cx, headCell } from './ui'
import { SplitLayout } from './SplitLayout'

type Update = (fn: (d: ProjectData) => ProjectData) => void

const REL_STYLE: Record<Rel, string> = {
  '': 'text-zinc-600',
  '<': 'bg-sky-500/15 text-sky-300',
  '=': 'bg-emerald-500/15 text-emerald-300',
  '>': 'bg-amber-500/15 text-amber-300',
}

const KEY_REL: Record<string, Rel> = { '<': '<', '=': '=', '>': '>', l: '<', e: '=', g: '>', Backspace: '', Delete: '' }
const MOVES: Record<string, [number, number]> = { ArrowUp: [-1, 0], ArrowDown: [1, 0], ArrowLeft: [0, -1], ArrowRight: [0, 1] }

function PrecGrid({
  prec,
  setCell,
  cycleCell,
}: {
  prec: Prec
  setCell: (a: string, b: string, v: Rel) => void
  cycleCell: (a: string, b: string) => void
}) {
  const { columns: cols, rows } = precTable(prec)
  const tableRef = useRef<HTMLTableElement>(null)
  const [hover, setHover] = useState('')

  const describe = (a: string, b: string) => setHover(`Tabuľka[${a}, ${b}] = ${relation(prec, a, b) || 'prázdne (chyba)'}`)

  const onKey = (e: KeyboardEvent<HTMLButtonElement>, r: number, c: number) => {
    if (e.key in KEY_REL) {
      e.preventDefault()
      setCell(cols[r], cols[c], KEY_REL[e.key])
    } else if (e.key in MOVES) {
      e.preventDefault()
      const [dr, dc] = MOVES[e.key]
      tableRef.current?.querySelector<HTMLButtonElement>(`button[data-r="${r + dr}"][data-c="${c + dc}"]`)?.focus()
    }
  }

  return (
    <>
      <div className="overflow-x-auto pb-1">
        <ClickSpark sparkColor={['#a5b4fc', '#7dd3fc', '#fcd34d']} sparkCount={7} sparkRadius={16} sparkSize={7} duration={380} className="inline-block! w-auto! h-auto!">
          <table ref={tableRef} className="border-collapse font-mono text-[13px]" onMouseLeave={() => setHover('')}>
            <thead>
              <tr>
                <th className={cx(headCell, 'text-[10px] leading-tight font-normal text-zinc-500')}>
                  zásobník ↓
                  <br />
                  vstup →
                </th>
                {cols.map((c) => (
                  <th key={c} className={headCell}>
                    {c}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map(({ terminal: r, relations }, ri) => (
                <tr key={r}>
                  <th className={headCell}>{r}</th>
                  {cols.map((c, ci) => {
                    const v = relations[ci]
                    return (
                      <td key={c} className="border border-white/10 p-0">
                        <button
                          type="button"
                          data-r={ri}
                          data-c={ci}
                          aria-label={`${r} ${c}: ${v || 'prázdne'}`}
                          className={cx(
                            'h-8 w-9 cursor-pointer text-[15px] font-bold transition-colors hover:bg-indigo-400/20 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-indigo-400',
                            REL_STYLE[v],
                          )}
                          onClick={() => cycleCell(r, c)}
                          onContextMenu={(e) => {
                            e.preventDefault()
                            setCell(r, c, '')
                          }}
                          onKeyDown={(e) => onKey(e, ri, ci)}
                          onMouseEnter={() => describe(r, c)}
                          onFocus={() => describe(r, c)}
                        >
                          {v}
                        </button>
                      </td>
                    )
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </ClickSpark>
      </div>
      <div className="mt-2 h-5 font-mono text-xs text-zinc-500">{hover}</div>
    </>
  )
}

export function PrecTab({ data, update }: { data: ProjectData; update: Update }) {
  const prec = data.prec
  const setPrec = (fn: (p: Prec) => Prec) => update((d) => ({ ...d, prec: fn(d.prec) }))
  const [termsDraft, setTermsDraft] = useState(prec.terminals.join(' '))
  const { problems, simulation: sim } = useMemo(() => analyzePrec(prec), [prec])
  const hasTable = prec.terminals.length > 0

  const termsKey = prec.terminals.join(' ')
  useEffect(() => setTermsDraft(termsKey), [termsKey])

  const applyTerms = () => setPrec((p) => setTerminals(p, parseTerminals(termsDraft)))

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Make the two sections left and right resizable"
  // Changes: Resizable two-column layout.
  return (
    <SplitLayout>
      <div className="min-w-0">
        <Panel title="Terminály tabuľky">
          <TextInput
            value={termsDraft}
            placeholder="+ * ( ) i"
            onChange={(e) => setTermsDraft(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && applyTerms()}
            aria-label="Terminály"
          />
          <Help>
            Oddelené medzerou, v poradí riadkov/stĺpcov. <code>$</code> sa pridá automaticky na koniec. Bunky existujúcich
            terminálov sa zachovajú.
          </Help>
          <div className="mt-3 flex flex-wrap gap-2">
            <PrimaryButton onClick={applyTerms}>Použiť</PrimaryButton>
            <DangerButton
              onClick={() => {
                if (confirm('Vymazať všetky bunky tabuľky?')) setPrec(clearRelations)
              }}
            >
              Vyčistiť bunky
            </DangerButton>
          </div>
        </Panel>

        <Panel title="Redukčné pravidlá">
          <TextArea
            rows={8}
            wrap="off"
            value={prec.rules}
            placeholder={'E -> E + E\nE -> E * E\nE -> ( E )\nE -> i'}
            onChange={(e) => setPrec((p) => ({ ...p, rules: e.target.value }))}
            aria-label="Redukčné pravidlá"
          />
          <Help>
            Rovnaký formát ako pri LL. Použijú sa na kontrolu a pri simulácii (redukcia <code>&lt;y → A</code>).
          </Help>
          <div className="mt-3">
            <Button
              onClick={() => {
                if (hasPrecTable(data) && !confirm('Nahradiť terminály, tabuľku, pravidlá a vstup simulácie príkladom?')) return
                update(loadPrecExample)
              }}
            >
              Príklad G<sub>expr2</sub>
            </Button>
          </div>
        </Panel>

        <Panel title="Simulácia precedenčnej analýzy">
          <TextInput value={prec.input} placeholder="i + i * i" onChange={(e) => setPrec((p) => ({ ...p, input: e.target.value }))} aria-label="Vstup simulácie" />
          <Help>
            Tokeny oddelené medzerou, <code>$</code> sa pridá automaticky.
          </Help>
          {sim && (
            <>
              <div className="mt-3">
                <ListTable head={['Zásobník', 'Op', 'Vstup', 'Pravidlo']}>
                  {sim.rows.map((r, i) => (
                    <tr key={i}>
                      <td>
                        {r.stack.map((it, j) => (
                          <span key={j} className={it.kind === 'm' ? 'font-bold text-sky-300' : it.kind === 'n' ? 'text-indigo-200' : ''}>
                            {j > 0 && ' '}
                            {it.s}
                          </span>
                        ))}
                      </td>
                      <td className="text-center font-bold">{r.op}</td>
                      <td>{r.input}</td>
                      <td className="text-zinc-400">{r.rule}</td>
                    </tr>
                  ))}
                </ListTable>
              </div>
              <ResultLine ok={sim.ok}>{sim.ok ? sim.message : `Chyba: ${sim.message}`}</ResultLine>
            </>
          )}
        </Panel>
      </div>

      <div className="min-w-0">
        <Panel title="Kontrola">
          <Problems items={problems} />
        </Panel>
        <Panel title="Precedenčná tabuľka">
          <Help>
            Riadok = terminál najbližšie vrcholu zásobníka, stĺpec = vstupný token. Klik prepína <code>&lt;</code> →{' '}
            <code>=</code> → <code>&gt;</code> → prázdne, pravý klik maže. Na označenej bunke: klávesy <code>&lt;</code>{' '}
            <code>=</code> <code>&gt;</code> (alebo <code>l</code> <code>e</code> <code>g</code>), <code>Backspace</code>, šípky.
          </Help>
          {hasTable && (
            <div className="mt-3">
              <PrecGrid
                prec={prec}
                setCell={(a, b, v) => setPrec((p) => setRelation(p, a, b, v))}
                cycleCell={(a, b) => setPrec((p) => cycleRelation(p, a, b))}
              />
            </div>
          )}
        </Panel>
      </div>
    </SplitLayout>
  )
}
